<script setup lang="ts">
import { ref, watch } from "vue";
import { item, type TrialAvailability, type Subscription } from "@papilio/api";
import { faNumber, faDate } from "@papilio/ui";
const props=defineProps<{customerId:number;admin?:boolean;canClaim:boolean}>();
const offer=ref<TrialAvailability|null>(null);const state=ref<"loading"|"ready"|"error">("loading");const error=ref("");const busy=ref(false);const key=ref(crypto.randomUUID());const accepted=ref<Subscription|null>(null);let version=0;
const reasons:Record<string,string>={plan_inactive:"The trial source plan is inactive.",plan_group_disabled:"The trial delivery group is inactive.",trial_source_missing:"The trial source plan was not found.",trial_disabled:"Trials are disabled.",trial_capacity:"Policy exceeds operational capacity.",trial_claim_limit:"This account has reached its trial claim limit.",trial_paid_customer:"This offer requires no previous paid purchase.",trial_active_exists:"An active trial subscription already exists.",trial_cooldown:"The trial cooldown has not ended.",customer_inactive:"Service access is disabled for this customer."};
async function load():Promise<void>{const token=++version;state.value="loading";error.value="";try{const result=await item<TrialAvailability>(props.admin?`/v1/admin/customers/${props.customerId}/trial-availability`:"/v1/customer/trials/availability");if(token!==version)return;offer.value=result;state.value="ready";}catch(cause){if(token!==version)return;state.value="error";error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}}
async function claim():Promise<void>{if(busy.value||!offer.value?.eligible||props.canClaim===false)return;busy.value=true;error.value="";const customer=props.customerId;try{const result=await item<Subscription>(props.admin?`/v1/admin/customers/${customer}/trial`:"/v1/customer/trials","POST",{request_key:key.value});if(customer!==props.customerId)return;accepted.value=result;key.value=crypto.randomUUID();await load();}catch(cause){if(customer!==props.customerId)return;error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}finally{busy.value=false;}}
watch(()=>props.customerId,()=>{accepted.value=null;key.value=crypto.randomUUID();void load();},{immediate:true});
</script>
<template><section class="card card-pad form-grid"><h2>Subscription Experimental</h2><p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="state==='loading'">Checking eligibility…</p><button type="button" class="btn secondary" :disabled="busy" @click="load">Refresh trial eligibility</button><template v-if="state==='ready' && offer"><p>Duration: {{ faNumber(offer.policy.duration_days) }} days · Quota: {{ faNumber(offer.policy.quota_bytes) }} bytes · Claims: {{ faNumber(offer.claims) }}</p><p v-if="offer.reason">{{ reasons[offer.reason]??'The trial is unavailable under the current policy.' }}</p><p v-if="offer.reason==='trial_cooldown' && offer.next_claim_at">Next claim available: {{ faDate(offer.next_claim_at) }}</p><p>Trials are free, require provisioning confirmation and do not renew automatically.</p><button v-if="canClaim!==false" type="button" class="btn" :disabled="busy||!offer.eligible" @click="claim">Download Subscription Experimental</button></template><div v-if="accepted" class="hint-box"><p>Subscription {{ faNumber(accepted.id) }} recorded. Provisioning needs confirmation.</p><RouterLink class="btn secondary" :to="admin?{path:'/subscriptions',query:{customer_id:customerId,subscription_id:accepted.id}}:{path:'/account',query:{subscription_id:accepted.id}}">View Subscription Experimental Registered</RouterLink></div></section></template>
